"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ArrowRight, ArrowUpRight, PhoneCall, MapPin, Play, MessageCircle, Heart, Users, BookOpen } from "lucide-react";

const customEase: [number, number, number, number] = [0.22, 1, 0.36, 1]; // Buttery Emil-like ease

